const normalizedConfiguredUrl = CONFIGURED_SUPABASE_URL?.trim().replace(/\/$/, '');
const hasOwnedDeploymentConfig =
  normalizedConfiguredUrl === OWNED_SUPABASE_URL &&
  Boolean(CONFIGURED_SUPABASE_KEY?.trim());
const SUPABASE_URL = OWNED_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = hasOwnedDeploymentConfig
